CREATE TABLE dbo.test_crm_order_opening_manifest(id int PRIMARY KEY CHECK(id=1),mapping_json nvarchar(max) NOT NULL,mapping_hash char(64) NOT NULL,scope_hash char(64) NOT NULL,scope_count int NOT NULL);
CREATE TABLE dbo.test_crm_order_opening_definitions(name sysname PRIMARY KEY,before_definition nvarchar(max) NULL,before_hash char(64) NULL,after_hash char(64) NOT NULL);
CREATE TABLE dbo.test_crm_order_opening_scope(source_id nvarchar(50) NOT NULL,source_stock_code nvarchar(120) NOT NULL,source_product_name nvarchar(250) NOT NULL,product_id bigint NOT NULL,native_stock_code nvarchar(50) NOT NULL,native_product_name nvarchar(250) NOT NULL,price_id bigint NOT NULL,price_source_key nvarchar(400) NOT NULL,source_unit_id bigint NOT NULL,main_unit_source_id bigint NOT NULL,price_tier int NOT NULL,currency nvarchar(3) NOT NULL,price_exact decimal(28,8) NOT NULL,native_price decimal(18,4) NOT NULL,unit nvarchar(40) NOT NULL,unit_factor decimal(28,8) NOT NULL,product_binding_hash char(64) NOT NULL,price_binding_hash char(64) NOT NULL,native_price_row_hash char(64) NOT NULL,evidence_sha256 char(64) NOT NULL,row_hash char(64) NOT NULL,PRIMARY KEY(source_id),UNIQUE(source_stock_code),UNIQUE(product_id),UNIQUE(price_id),FOREIGN KEY(product_id) REFERENCES dbo.products(id),FOREIGN KEY(price_id) REFERENCES dbo.product_prices(id));
CREATE TABLE dbo.test_crm_order_opening_lines(request_id uniqueidentifier NOT NULL REFERENCES dbo.test_crm_order_requests(request_id),item_id bigint NOT NULL REFERENCES dbo.sales_order_items(id),source_id nvarchar(50) NOT NULL REFERENCES dbo.test_crm_order_opening_scope(source_id),scope_row_hash char(64) NOT NULL,price_exact decimal(28,8) NOT NULL,native_price decimal(18,4) NOT NULL,price_id bigint NOT NULL,price_source_key nvarchar(400) NOT NULL,PRIMARY KEY(request_id,item_id));
INSERT dbo.test_crm_order_opening_scope(source_id,source_stock_code,source_product_name,product_id,native_stock_code,native_product_name,price_id,price_source_key,source_unit_id,main_unit_source_id,price_tier,currency,price_exact,native_price,unit,unit_factor,product_binding_hash,price_binding_hash,native_price_row_hash,evidence_sha256,row_hash) SELECT s.source_id,s.source_stock_code,s.source_product_name,s.product_id,s.native_stock_code,s.native_product_name,s.price_id,s.price_source_key,s.source_unit_id,s.main_unit_source_id,s.price_tier,s.currency,s.price_exact,s.native_price,s.unit,s.unit_factor,s.product_binding_hash,s.price_binding_hash,s.native_price_row_hash,s.evidence_sha256,LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',(SELECT s.source_id,s.source_stock_code,s.source_product_name,s.product_id,s.native_stock_code,s.native_product_name,s.price_id,s.price_source_key,s.source_unit_id,s.main_unit_source_id,s.price_tier,s.currency,s.price_exact,s.native_price,s.unit,s.unit_factor,s.product_binding_hash,s.price_binding_hash,s.native_price_row_hash,s.evidence_sha256 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)) FROM OPENJSON(@mapping_json,'$.products') WITH(source_id nvarchar(50) '$.sourceId',source_stock_code nvarchar(120) '$.stockCode',source_product_name nvarchar(250) '$.productName',product_id bigint '$.nativeProductId',native_stock_code nvarchar(50) '$.nativeStockCode',native_product_name nvarchar(250) '$.nativeProductName',price_id bigint '$.nativePriceId',price_source_key nvarchar(400) '$.priceSourceKey',source_unit_id bigint '$.unitSourceId',main_unit_source_id bigint '$.mainUnitSourceId',price_tier int '$.tier',currency nvarchar(3) '$.currency',price_exact decimal(28,8) '$.priceExact8',native_price decimal(18,4) '$.nativePriceExact4',unit nvarchar(40) '$.unit',unit_factor decimal(28,8) '$.factorExact8',product_binding_hash char(64) '$.productBindingHash',price_binding_hash char(64) '$.priceBindingHash',native_price_row_hash char(64) '$.nativePriceRowHash',evidence_sha256 char(64) '$.evidenceSha256') s;
IF (SELECT COUNT(*) FROM dbo.test_crm_order_opening_scope) NOT BETWEEN 1 AND 50 THROW 51099,'CRM_TEST_ACTUAL_INSTALL_METADATA_REQUIRED',1;
INSERT dbo.test_crm_order_opening_manifest SELECT 1,@mapping_json,LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',@mapping_json),2)),LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',(SELECT s.source_id,s.row_hash FROM dbo.test_crm_order_opening_scope s ORDER BY s.source_id FOR JSON PATH)),2)),(SELECT COUNT(*) FROM dbo.test_crm_order_opening_scope);
INSERT dbo.test_crm_order_opening_definitions(name,before_definition,before_hash,after_hash) SELECT name,OBJECT_DEFINITION(object_id),LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(object_id)),2)),LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(object_id)),2)) FROM sys.procedures WHERE schema_id=SCHEMA_ID(N'dbo') AND name IN(N'usp_test_crm_order_context',N'usp_test_crm_order_create',N'usp_test_crm_order_read');
-- Scope is validated before any procedure replacement. No native-card DML.
INSERT #E02Selected SELECT product_id FROM dbo.test_crm_order_opening_scope; IF (SELECT COUNT(*) FROM #E02Selected)<>(SELECT COUNT(*) FROM #E02Selected q JOIN dbo.test_crm_order_opening_scope s WITH(HOLDLOCK) ON s.product_id=q.product_id
JOIN erp_migration.accepted_price_products b WITH(HOLDLOCK) ON b.product_id=s.product_id
JOIN erp_migration.accepted_price_values v WITH(HOLDLOCK) ON v.price_id=s.price_id AND v.product_id=b.product_id
JOIN dbo.products p WITH(HOLDLOCK) ON p.id=b.product_id JOIN dbo.product_prices n WITH(HOLDLOCK) ON n.id=v.price_id
JOIN erp_migration.records r WITH(HOLDLOCK) ON r.run_id=N'VEGA-OPENING-TEST-20261004-06' AND r.entity=N'products' AND r.source_key=b.product_source_key
JOIN erp_migration.records pr WITH(HOLDLOCK) ON pr.run_id=N'VEGA-OPENING-TEST-20261004-06' AND pr.entity=N'prices' AND pr.source_key=v.price_source_key
WHERE s.source_id=N'vega-'+b.source_id AND b.product_source_key=N'VEGA_CAPTURE_20260930_01/F0102/TBLSTOKLAR/'+b.source_id
AND CONVERT(varbinary(max),s.source_stock_code)=CONVERT(varbinary(max),b.stock_code) AND CONVERT(varbinary(max),s.source_product_name)=CONVERT(varbinary(max),b.product_name) AND CONVERT(varbinary(max),s.native_stock_code)=CONVERT(varbinary(max),p.stock_code) AND CONVERT(varbinary(max),s.native_product_name)=CONVERT(varbinary(max),p.name)
AND CONVERT(varbinary(max),p.stock_code)=CONVERT(varbinary(max),b.stock_code) AND CONVERT(varbinary(max),p.name)=CONVERT(varbinary(max),b.product_name) AND CONVERT(varbinary(max),p.source_record_key)=CONVERT(varbinary(max),b.native_source_key) AND CONVERT(varbinary(max),p.currency_code)=CONVERT(varbinary(max),b.currency_code)
AND p.is_active=1 AND p.is_deleted=0 AND p.unit=N'ADET' AND b.unit=N'ADET' AND s.unit=N'ADET' AND s.unit_factor=1
AND JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.unitStatus')=N'VERIFIED_ADET_FACTOR_1' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.unitFactor'))=1
AND TRY_CONVERT(bigint,JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.mainUnitSourceId'))=b.main_unit_source_id AND s.main_unit_source_id=b.main_unit_source_id AND s.source_unit_id=b.main_unit_source_id
AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE a.product_id=p.id)=1 AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE CONVERT(varchar(80),a.source_product_id)=b.source_id)=1
AND EXISTS(SELECT 1 FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE a.product_id=p.id AND CONVERT(varchar(80),a.source_product_id)=b.source_id)
AND LOWER(b.binding_hash)=s.product_binding_hash AND LOWER(v.binding_hash)=s.price_binding_hash AND LOWER(v.native_row_hash)=s.native_price_row_hash
AND LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',(SELECT b.product_id,b.product_source_key,b.source_id,b.native_source_key,b.stock_code,b.product_name,b.currency_code,b.unit,b.main_unit_source_id,b.stage_payload_hash,b.stage_sql_hash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2))=LOWER(b.binding_hash) AND LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',(SELECT v.price_id,v.product_id,v.product_source_key,v.price_source_key,v.source_unit_id,v.price_type,v.price_tier,v.currency_code,v.price_exact,v.is_main_unit,v.stage_payload_hash,v.stage_sql_hash,v.native_row_hash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2))=LOWER(v.binding_hash)
AND r.payload_hash=b.stage_payload_hash AND CONVERT(char(64),HASHBYTES('SHA2_256',r.payload_json),2)=b.stage_sql_hash AND pr.payload_hash=v.stage_payload_hash AND CONVERT(char(64),HASHBYTES('SHA2_256',pr.payload_json),2)=v.stage_sql_hash
AND v.product_source_key=b.product_source_key AND v.price_source_key=s.price_source_key AND v.price_type=N'sale' AND v.price_tier=1 AND s.price_tier=1 AND v.is_main_unit=1
AND v.source_unit_id=s.source_unit_id AND v.currency_code=s.currency AND v.price_exact=s.price_exact AND CONVERT(decimal(18,4),ROUND(v.price_exact,4))=s.native_price
AND v.price_source_key=b.product_source_key+N'/PRICE/sale/'+CONVERT(nvarchar(20),v.source_unit_id)+N'/1/'+v.currency_code
AND n.product_id=v.product_id AND n.price_type=N'sale' AND n.price_tier=v.price_tier AND n.currency_code=v.currency_code AND n.source_unit_id=v.source_unit_id AND n.price=v.price_exact
AND LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',(SELECT n.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2))=LOWER(v.native_row_hash)
AND (SELECT COUNT(*) FROM dbo.product_prices z WITH(HOLDLOCK) WHERE z.product_id=v.product_id AND CONVERT(varbinary(max),z.price_type)=CONVERT(varbinary(max),v.price_type) AND z.price_tier=v.price_tier AND CONVERT(varbinary(max),z.currency_code)=CONVERT(varbinary(max),v.currency_code) AND z.source_unit_id=v.source_unit_id)=1) THROW 51097,'CRM_TEST_OPENING_BINDING_DRIFT',1;
IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WITH(HOLDLOCK) WHERE (h.entity=N'product' AND (h.native_id IN(SELECT product_id FROM #E02Selected) OR h.source_id IN(SELECT SUBSTRING(s.source_id,6,50) FROM dbo.test_crm_order_opening_scope s JOIN #E02Selected q ON q.product_id=s.product_id))) OR (h.entity=N'customer' AND (h.native_id=593 OR h.native_entity_id IN(SELECT party_entity_id FROM dbo.customers WHERE id=593)))) THROW 51098,'CRM_TEST_PRODUCT_QUARANTINED',1;
