EXEC sys.sp_executesql N'ALTER PROCEDURE dbo.usp_test_crm_order_context @actor_id BIGINT,@crm_actor_id NVARCHAR(80) WITH EXECUTE AS OWNER AS BEGIN
SET NOCOUNT ON; SET XACT_ABORT ON; SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRY BEGIN TRANSACTION; IF @crm_actor_id IS NULL OR LEN(@crm_actor_id) NOT BETWEEN 1 AND 80 OR NOT EXISTS(SELECT 1 FROM dbo.users u WITH(HOLDLOCK) JOIN dbo.roles r WITH(HOLDLOCK) ON r.id=u.role_id WHERE u.id=@actor_id AND u.is_active=1 AND (r.code COLLATE Latin1_General_100_BIN2 IN(N''admin'',N''owner_manager'',N''owner_partner'') OR EXISTS(SELECT 1 FROM dbo.permissions a WITH(HOLDLOCK) WHERE a.role_id=u.role_id AND ((a.permission_key=N''sales.view'' AND (a.can_view=1 OR a.can_create=1 OR a.can_update=1 OR a.can_approve=1)) OR (a.permission_key IN(N''sales.draft.write'',N''sales_invoices.manage'') AND a.can_view=1))))) THROW 51094,''CRM_TEST_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.customers WITH(HOLDLOCK) WHERE id=593 AND customer_code COLLATE Latin1_General_100_BIN2=N''TEST-V70-20260929-C'' AND is_active=1 AND is_deleted=0) THROW 51094,''CRM_TEST_SCOPE_REQUIRED'',1; IF DB_NAME() COLLATE Latin1_General_100_BIN2<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CONVERT(nvarchar(128),SERVERPROPERTY(''ServerName'')) COLLATE Latin1_General_100_BIN2<>N''Semih\MELISADEV'' THROW 51090,''CRM_TEST_DATABASE_REQUIRED'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.runs WITH(HOLDLOCK) WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND status COLLATE Latin1_General_100_BIN2=N''COMMITTED'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'') THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.accepted_price_manifest WITH(HOLDLOCK) WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND bindings_hash=''5842be926d493c8973566fd922ef840d9fe6f7cecd9d83f17f506be5aa3fbd72'' AND source_as_of=N''2026-09-30'' AND sealed=1 AND product_count=16622 AND price_count=63774) OR (SELECT COUNT(*) FROM erp_migration.accepted_price_products)<>16622 OR (SELECT COUNT(*) FROM erp_migration.accepted_price_values)<>63774 THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_manifest WITH(HOLDLOCK) WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'' AND sealed=1 AND seal_hash=''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' AND source_rows=176 AND native_holds=172 AND not_present=4) THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WITH(HOLDLOCK))<>176 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NOT NULL)<>172 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NULL)<>4 OR EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.entity,h.source_key,h.source_id,h.source_company,h.source_code,h.source_name,h.native_id,h.native_entity_id,h.native_source_key,h.native_code,h.native_name,h.status,h.reasons_json,h.binding_basis FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2))<>LOWER(h.row_hash)) THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.source_key,h.row_hash FROM erp_migration.operation_quarantine_holds h ORDER BY h.source_key FOR JSON PATH)),2))<>''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' OR (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF (SELECT COUNT(*) FROM dbo.test_crm_order_opening_manifest)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.test_crm_order_opening_manifest m WHERE m.id=1 AND m.mapping_hash=LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',m.mapping_json),2)) AND m.scope_count BETWEEN 1 AND 50 AND m.scope_count=(SELECT COUNT(*) FROM dbo.test_crm_order_opening_scope) AND m.scope_hash=LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT s.source_id,s.row_hash FROM dbo.test_crm_order_opening_scope s ORDER BY s.source_id FOR JSON PATH)),2))) OR EXISTS(SELECT 1 FROM dbo.test_crm_order_opening_scope s WHERE s.row_hash<>LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT s.source_id,s.source_stock_code,s.source_product_name,s.product_id,s.native_stock_code,s.native_product_name,s.price_id,s.price_source_key,s.source_unit_id,s.main_unit_source_id,s.price_tier,s.currency,s.price_exact,s.native_price,s.unit,s.unit_factor,s.product_binding_hash,s.price_binding_hash,s.native_price_row_hash,s.evidence_sha256 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2))) THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
IF (SELECT COUNT(*) FROM dbo.test_crm_order_opening_definitions)<>7 OR EXISTS(SELECT 1 FROM dbo.test_crm_order_opening_definitions d LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N''dbo.''+d.name) WHERE o.object_id IS NULL OR d.after_hash<>LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(o.object_id)),2)) OR (o.type=N''TR'' AND OBJECTPROPERTY(o.object_id,''ExecIsTriggerDisabled'')<>0)) THROW 51099,''CRM_TEST_OPENING_NOT_READY'',1;
CREATE TABLE #E02Selected(product_id bigint PRIMARY KEY); INSERT #E02Selected SELECT product_id FROM dbo.test_crm_order_opening_scope; IF (SELECT COUNT(*) FROM #E02Selected)<>(SELECT COUNT(*) FROM #E02Selected q JOIN dbo.test_crm_order_opening_scope s WITH(HOLDLOCK) ON s.product_id=q.product_id
JOIN erp_migration.accepted_price_products b WITH(HOLDLOCK) ON b.product_id=s.product_id
JOIN erp_migration.accepted_price_values v WITH(HOLDLOCK) ON v.price_id=s.price_id AND v.product_id=b.product_id
JOIN dbo.products p WITH(HOLDLOCK) ON p.id=b.product_id JOIN dbo.product_prices n WITH(HOLDLOCK) ON n.id=v.price_id
JOIN erp_migration.records r WITH(HOLDLOCK) ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''products'' AND r.source_key=b.product_source_key
JOIN erp_migration.records pr WITH(HOLDLOCK) ON pr.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND pr.entity=N''prices'' AND pr.source_key=v.price_source_key
WHERE s.source_id=N''vega-''+b.source_id AND b.product_source_key=N''VEGA_CAPTURE_20260930_01/F0102/TBLSTOKLAR/''+b.source_id
AND CONVERT(varbinary(max),s.source_stock_code)=CONVERT(varbinary(max),b.stock_code) AND CONVERT(varbinary(max),s.source_product_name)=CONVERT(varbinary(max),b.product_name) AND CONVERT(varbinary(max),s.native_stock_code)=CONVERT(varbinary(max),p.stock_code) AND CONVERT(varbinary(max),s.native_product_name)=CONVERT(varbinary(max),p.name)
AND CONVERT(varbinary(max),p.stock_code)=CONVERT(varbinary(max),b.stock_code) AND CONVERT(varbinary(max),p.name)=CONVERT(varbinary(max),b.product_name) AND CONVERT(varbinary(max),p.source_record_key)=CONVERT(varbinary(max),b.native_source_key) AND CONVERT(varbinary(max),p.currency_code)=CONVERT(varbinary(max),b.currency_code)
AND p.is_active=1 AND p.is_deleted=0 AND p.unit=N''ADET'' AND b.unit=N''ADET'' AND s.unit=N''ADET'' AND s.unit_factor=1
AND JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitStatus'')=N''VERIFIED_ADET_FACTOR_1'' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.unitFactor''))=1
AND TRY_CONVERT(bigint,JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.mainUnitSourceId''))=b.main_unit_source_id AND s.main_unit_source_id=b.main_unit_source_id AND s.source_unit_id=b.main_unit_source_id
AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE a.product_id=p.id)=1 AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE CONVERT(varchar(80),a.source_product_id)=b.source_id)=1
AND EXISTS(SELECT 1 FROM dbo.product_source_aliases a WITH(HOLDLOCK) WHERE a.product_id=p.id AND CONVERT(varchar(80),a.source_product_id)=b.source_id)
AND LOWER(b.binding_hash)=s.product_binding_hash AND LOWER(v.binding_hash)=s.price_binding_hash AND LOWER(v.native_row_hash)=s.native_price_row_hash
