IF NOT EXISTS(SELECT 1 FROM dbo.test_crm_order_requests WHERE request_id=@request_id AND actor_id=@actor_id AND CONVERT(varbinary(max),crm_actor_id)=CONVERT(varbinary(max),@crm_actor_id) AND conversation_id=@conversation_id AND customer_id=@customer_id AND peer=N''905387217733'' AND payload_hash=@payload_hash AND CONVERT(varbinary(max),items_json)=CONVERT(varbinary(max),@items_json) AND exchange_rate=@exchange_rate) THROW 51093,''CRM_TEST_REQUEST_CONFLICT'',1;
